def ndiv(n): return sum(1 for d in range(1, n+1) if n % d == 0)
def sdiv(n): return sum(d for d in range(1, n+1) if n % d == 0)
def tz(n):
    c=0; p=5
    while p<=n: c+=n//p; p*=5
    return c
MATH_INSTR = 'Please reason step by step, and put your final answer within \\boxed{}.'
def m_gen(rng, kind):
    if kind==0:
        n = rng.choice([360,420,504,540,630,720,756,840,900,960,1008,1080,1260,1440,1680,1800,2016,2520])
        return f'How many positive divisors does {n} have?', ndiv(n)
    if kind==1:
        n = rng.choice([84,90,120,126,132,144,150,168,180,196,210,220,240,252,270,280])
        return f'What is the sum of all positive divisors of {n}?', sdiv(n)
    if kind==2:
        a,b,m = rng.choice([3,7,11,13,17]), rng.randint(50,500), rng.choice([23,29,31,37,41,43])
        return f'What is the remainder when ${a}^{{{b}}}$ is divided by ${m}$?', pow(a,b,m)
    if kind==3:
        N = rng.choice([500,600,750,1000,1200,1500]); a,b = rng.sample([3,4,6,7,9],2); c = rng.choice([5,10,11])
        cnt = sum(1 for x in range(1,N+1) if (x%a==0 or x%b==0) and x%c!=0)
        return f'How many integers from 1 to {N} inclusive are divisible by {a} or {b} but not by {c}?', cnt
    if kind==4:
        w = rng.choice(['BANANAS','COMMITTEE','STATISTICS','MISSISSIPPI','BOOKKEEPER','PEPPERMINT','ASSESSMENT','TENNESSEE'])
        from math import factorial
        cnt = factorial(len(w)); 
        for ch,v in collections.Counter(w).items(): cnt //= factorial(v)
        return f'How many distinct arrangements of the letters of the word {w} are there?', cnt
    if kind==5:
        n,k,c = rng.randint(6,10), rng.randint(2,4), rng.choice([2,3])
        return f'What is the coefficient of $x^{k}$ in the expansion of $(1+{c}x)^{{{n}}}$?', math.comb(n,k)*c**k
    if kind==6:
        a,b = rng.choice([7,13,17,19,23]), rng.randint(100,999)
        return f'What are the last two digits of ${a}^{{{b}}}$? Give the answer as an integer from 0 to 99.', pow(a,b,100)
    if kind==7:
        n = rng.choice([100,125,150,200,250,300,365,500,625,1000])
        return f'How many trailing zeros does ${n}!$ have?', tz(n)
    if kind==8:
        s = rng.randint(5,20)
        cnt = sum(1 for x in range(100,1000) if sum(map(int,str(x)))==s)
        return f'How many three-digit positive integers have digits that sum to {s}?', cnt
    if kind==9:
        n, lo = rng.randint(10,20), rng.randint(1,3)
        cnt = math.comb(n - 3*lo + 2, 2)
        return f'How many ordered triples of integers $(a, b, c)$ with $a, b, c \\geq {lo}$ satisfy $a + b + c = {n}$?', cnt
    if kind==10:
        n = rng.randint(7,20)
        return f'How many diagonals does a convex polygon with {n} sides have?', n*(n-3)//2
    if kind==11:
        a, r, n = rng.randint(2,6), rng.choice([2,3]), rng.randint(5,9)
        return f'What is the sum of the first {n} terms of the geometric sequence {a}, {a*r}, {a*r*r}, ...?', a*(r**n-1)//(r-1)
rngm = random.Random(4242); MATHQ = []
seen = set()
while len(MATHQ) < 256:
    k = len(MATHQ) % 12; q, ans = m_gen(rngm, k)
    if q in seen: continue
    seen.add(q); MATHQ.append(dict(q=q, ans=int(ans), kind=k, prompt=q + '\n\n' + MATH_INSTR))
json.dump([x['prompt'] for x in MATHQ], open('/work/math18_prompts.json','w')); json.dump(MATHQ, open('/work/math18_items.json','w'))
print(len(MATHQ), MATHQ[3]['prompt'][:160], MATHQ[3]['ans'])
with open('/work/notes.md','a') as f:
