rngm = random.Random(4242); MATHQ = []; seen = set(); tries = 0
while len(MATHQ) < 256 and tries < 20000:
    tries += 1; k = rngm.randrange(12); q, ans = m_gen(rngm, k)
    if q in seen: continue
    seen.add(q); MATHQ.append(dict(q=q, ans=int(ans), kind=k, prompt=q + '\n\n' + MATH_INSTR))
print(len(MATHQ), tries, collections.Counter(x['kind'] for x in MATHQ))
json.dump([x['prompt'] for x in MATHQ], open('/work/math18_prompts.json','w')); json.dump(MATHQ, open('/work/math18_items.json','w'))
print(MATHQ[3]['prompt'][:200], '->', MATHQ[3]['ans'])
